// Only the server-side resolver can authorize the exact batch behind a shared alias.
$publicPrint=isset($publicPrintCodes,$publicPrintUrl)&&is_string($publicPrintCodes)&&$publicPrintCodes===($_GET['codigos']??null);
if(!$publicPrint){if(!current_user()){$requested=$_GET['codigos']??$_GET['codigo']??'';if(is_string($requested)&&preg_match('/^[0-9]{8}(?:,[0-9]{8}){0,99}$/D',$requested))$_SESSION['pending_label_codes']=$requested;}require_account();}
require_once __DIR__.'/includes/stock.php'; require_once __DIR__.'/includes/stock-icons.php';
$labelBase=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/etiqueta.php')),'/').'/';
$raw=$_GET['codigos']??$_GET['codigo']??''; $codes=is_string($raw)?array_values(array_unique(explode(',',$raw))):[]; $labels=[]; $error='';
try {
    if (!$codes||count($codes)>100) throw new CatalogException('Elige entre 1 y 100 etiquetas.',422);
    $db=database();
    if($publicPrint){
        $q=$db->prepare('SELECT l.code,l.reserved_until,COALESCE(p.activated,0) AS activated,COALESCE(p.prepared_until,0) AS prepared_until FROM pallet_labels l LEFT JOIN pallets p ON p.id=l.pallet_id WHERE l.code=?');
        foreach($codes as $code){if(!preg_match('/^[0-9]{8}$/D',$code))throw new CatalogException('Enlace no disponible.',404);$q->execute([$code]);$label=$q->fetch(PDO::FETCH_ASSOC);if(!$label)throw new CatalogException('Etiqueta no disponible.',404);$labels[]=$label;}
    }else{
    $db->beginTransaction();
    if ($db->getAttribute(PDO::ATTR_DRIVER_NAME)==='pgsql') $db->query('SELECT pg_advisory_xact_lock(72684623)'); else $db->exec('UPDATE stock_mutex SET revision=revision+1 WHERE id=1');
    stock_expire($db);
    foreach($codes as $code){$p=stock_detail($db,$code,(int)current_user()['id']);$label=stock_label($db,$code);if(!stock_is_admin($db,(int)current_user()['id'])&&!$p['can_edit']&&(!$p['available']||(int)$label['reserved_by']!==(int)current_user()['id']))throw new CatalogException('No tienes permiso para imprimir esta etiqueta.',403);$labels[]=['code'=>$code,'activated'=>$p['activated']??0,'reserved_until'=>$label['reserved_until'],'prepared_until'=>$p['prepared_until']??0];}
    $db->commit();
    }
} catch(Throwable $exception){if(isset($db)&&$db->inTransaction())$db->rollBack();http_response_code($exception instanceof CatalogException?$exception->status:503);$error=$exception instanceof CatalogException?$exception->getMessage():'No pudimos cargar las etiquetas.';}
