c="js/pallet-label-pdf.js?v=<?= substr(sha1_file(__DIR__.'/js/pallet-label-pdf.js'),0,12) ?>"></script><script src="js/share-links.js?v=<?= (int)app_release()['version'] ?>"></script><script src="js/label-files.js?v=<?= substr(sha1_file(__DIR__.'/js/label-files.js'),0,12) ?>"></script><script src="js/label-page.js?v=<?= substr(sha1_file(__DIR__.'/js/label-page.js'),0,12) ?>"></script></body></html>
